// Original, dependency-free replicas of common accessible component patterns.
// They intentionally exercise roles and state shapes found across WAI-ARIA APG,
// Base UI, Radix, MUI and shadcn without copying any library implementation.
const escapeHtml = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');

export const componentCases = [
  {id:'accordion',family:'disclosure',intent:'Expand Returns policy, mark that section reviewed, and finish on the completion screen.',expected:{panel:'Returns policy'}},
  {id:'tabs',family:'navigation',intent:'Open the Billing tab and download the September invoice on this fake page.',expected:{tab:'Billing',invoice:'September'}},
  {id:'dropdown-menu',family:'menu',intent:'Open the Actions menu and duplicate the draft.',expected:{action:'Duplicate draft'}},
  {id:'nested-menu',family:'menu',intent:'Use the Actions menu, then the Share submenu, to copy a private link.',expected:{share:'Copy private link'}},
  {id:'dialog-form',family:'overlay',intent:'Open Invite member, enter the supplied email, choose Viewer access, and add the member.',values:{email:'viewer@example.test'},expected:{email:'viewer@example.test',access:'viewer'}},
  {id:'alert-dialog',family:'overlay',intent:'Open Delete project, then cancel the deletion and keep the project.',expected:{decision:'cancel'}},
  {id:'radio-switch',family:'selection',intent:'Choose the Pro plan, enable annual billing, and save the billing settings.',expected:{plan:'pro',annual:true}},
  {id:'toggle-group',family:'selection',intent:'Choose Center alignment and Compact density, then apply the view settings.',expected:{alignment:'center',density:'compact'}},
  {id:'custom-select',family:'selection',intent:'Choose West warehouse from the custom warehouse selector and save.',expected:{warehouse:'west'}},
  {id:'multi-select',family:'selection',intent:'Select Analytics and Security in the multi-select list, then apply the teams.',expected:{teams:['analytics','security']}},
  {id:'pagination',family:'navigation',intent:'Go to page 3 and open Invoice 27.',expected:{page:3,invoice:'27'}},
  {id:'sortable-table',family:'data',intent:'Sort the project table by name ascending, then open Orion.',expected:{sort:'name-ascending',project:'Orion'}},
  {id:'tree-view',family:'data',intent:'Expand Finance, select Q4 forecast, and open that report.',expected:{branch:'Finance',report:'Q4 forecast'}},
  {id:'command-palette',family:'overlay',intent:'Open the command palette, search using the supplied query, and run Create report.',values:{query:'report'},expected:{command:'Create report'}},
  {id:'popover-filters',family:'overlay',intent:'Open Filters, enable Overdue only, and apply the filters.',expected:{overdue:true,unassigned:false}},
  {id:'stepper',family:'workflow',intent:'Create a private project named with the supplied project name and finish the stepper.',values:{projectName:'Northstar review'},expected:{name:'Northstar review',access:'private'}},
  {id:'drawer',family:'overlay',intent:'Open the account drawer and go to API keys.',expected:{destination:'API keys'}},
  {id:'carousel',family:'navigation',intent:'Move through the carousel until Alpine lodge is visible, then choose that stay.',expected:{stay:'Alpine lodge'}},
  {id:'delayed-toast',family:'feedback',intent:'Run the fake sync and wait until the page confirms Sync complete.',expected:{status:'Sync complete'}},
  {id:'spinbutton',family:'input',intent:'Set Seats to the supplied count and save capacity.',values:{seats:'12'},expected:{seats:12}},
  {id:'tri-state-checkbox',family:'selection',intent:'Select all notification channels using the parent checkbox, then save.',expected:{email:true,sms:true,push:true}},
  {id:'rating',family:'selection',intent:'Choose a 4 star rating and submit the review.',expected:{rating:4}},
  {id:'breadcrumb',family:'navigation',intent:'Use the breadcrumb trail to open Workspace, then open Notifications.',expected:{destination:'Notifications'}},
  {id:'missing-target',family:'boundary',intent:'Open the Billing settings panel. If that target is absent, return control without changing anything.',reason:'handoff',expected:null},
  {id:'file-upload',family:'input',intent:'Upload the supplied contract file and submit it.',values:{contract:'__COMPONENT_FIXTURE_PDF__'},expected:{uploaded:true}},
  {id:'hover-card',family:'overlay',intent:'Open the keyboard shortcuts link that is available only in the Account hover card.',expected:{destination:'Keyboard shortcuts'}},
];

const sharedScript = id => `
const caseId=${JSON.stringify(id)};
async function emit(event){await fetch('/events',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(event)})}
async function finish(value,label='Component task complete'){await emit({type:'complete',caseId,value});document.body.innerHTML='<main><h1>'+label+'</h1><p>The local fixture recorded the requested state.</p></main>'}
`;

const shell = (id,title,body,script='') => `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${escapeHtml(title)} · Component gym</title><style>
*{box-sizing:border-box}body{font:17px system-ui;margin:0;background:#f3f5f8;color:#18202a}main{max-width:780px;margin:32px auto;padding:28px;background:white;border:1px solid #ccd3dc;border-radius:14px}button,input,select,textarea{font:inherit;padding:9px;margin:5px}button{cursor:pointer}button[disabled]{cursor:not-allowed}label{display:block;margin:12px 0}.panel,[role=dialog],[role=alertdialog],[role=menu],[role=listbox],[role=tree]{border:1px solid #9ca8b7;padding:14px;margin:12px 0;border-radius:8px}[hidden]{display:none!important}[role=option],[role=menuitem],[role=menuitemcheckbox],[role=menuitemradio],[role=treeitem]{display:block;width:100%;text-align:left}.tabs{display:flex;gap:6px}.tabs [aria-selected=true],[aria-pressed=true],[aria-selected=true]{background:#153e75;color:white}.spacer{height:950px}.toast{border:2px solid #19723a;padding:12px;margin-top:20px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #b6bfca;padding:8px;text-align:left}nav ol{display:flex;gap:8px;list-style:none;padding:0}.slides article{padding:20px;border:1px solid #aaa}
</style></head><body><main><h1>${escapeHtml(title)}</h1>${body}</main><script>${sharedScript(id)}${script}</script></body></html>`;

const pages = {
  accordion:()=>shell('accordion','Policy sections',`
    <section><h2><button aria-expanded="false" aria-controls="returns">Returns policy</button></h2><div id="returns" class="panel" hidden><p>Returns are accepted for 30 days.</p><button id="review">Mark reviewed</button></div></section>
    <section><h2><button aria-expanded="false" aria-controls="shipping">Shipping policy</button></h2><div id="shipping" class="panel" hidden><p>Standard shipping takes five days.</p></div></section>`,`
document.querySelectorAll('[aria-controls]').forEach(button=>button.onclick=()=>{const panel=document.getElementById(button.getAttribute('aria-controls'));const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));panel.hidden=open});
review.onclick=()=>finish({panel:'Returns policy'});`),

  tabs:()=>shell('tabs','Account',`<div class="tabs" role="tablist" aria-label="Account sections"><button role="tab" aria-selected="true" aria-controls="profile">Profile</button><button role="tab" aria-selected="false" aria-controls="billing">Billing</button><button role="tab" aria-selected="false" aria-controls="security">Security</button></div><section id="profile" role="tabpanel"><p>Profile settings.</p></section><section id="billing" role="tabpanel" hidden><h2>Invoices</h2><button id="invoice">Download September invoice</button></section><section id="security" role="tabpanel" hidden><p>Security settings.</p></section>`,`
document.querySelectorAll('[role=tab]').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('[role=tab]').forEach(x=>x.setAttribute('aria-selected',String(x===tab)));document.querySelectorAll('[role=tabpanel]').forEach(x=>x.hidden=x.id!==tab.getAttribute('aria-controls'))});invoice.onclick=()=>finish({tab:'Billing',invoice:'September'});`),

  'dropdown-menu':()=>shell('dropdown-menu','Draft editor',`<button id="trigger" aria-haspopup="menu" aria-expanded="false">Actions</button><div id="menu" role="menu" hidden><button role="menuitem">Rename draft</button><button role="menuitem" id="duplicate">Duplicate draft</button><button role="menuitem">Move draft</button></div>`,`trigger.onclick=()=>{menu.hidden=false;trigger.setAttribute('aria-expanded','true')};duplicate.onclick=()=>finish({action:'Duplicate draft'});`),

  'nested-menu':()=>shell('nested-menu','Document',`<button id="actions" aria-haspopup="menu" aria-expanded="false">Actions</button><div id="rootmenu" role="menu" hidden><button role="menuitem">Rename</button><button id="share" role="menuitem" aria-haspopup="menu" aria-expanded="false">Share</button></div><div id="submenu" role="menu" aria-label="Share" hidden><button role="menuitem">Copy public link</button><button role="menuitem" id="private">Copy private link</button></div>`,`actions.onclick=()=>{rootmenu.hidden=false;actions.setAttribute('aria-expanded','true')};share.onclick=()=>{submenu.hidden=false;share.setAttribute('aria-expanded','true')};private.onclick=()=>finish({share:'Copy private link'});`),

  'dialog-form':()=>shell('dialog-form','Members',`<button id="invite">Invite member</button><dialog id="dialog"><h2>Invite member</h2><form id="form"><label>Email <input id="email" type="email" required></label><label>Access <select id="access"><option value="editor">Editor</option><option value="viewer">Viewer</option><option value="admin">Admin</option></select></label><button>Add member</button><button type="button" id="cancel">Cancel</button></form></dialog>`,`invite.onclick=()=>dialog.showModal();cancel.onclick=()=>dialog.close();form.onsubmit=e=>{e.preventDefault();finish({email:email.value,access:access.value})};`),

  'alert-dialog':()=>shell('alert-dialog','Danger zone',`<button id="open-alert">Delete project</button><div id="alert" role="alertdialog" aria-modal="true" aria-labelledby="heading" hidden><h2 id="heading">Delete project?</h2><p>This cannot be undone.</p><button id="confirm">Delete forever</button><button id="cancel">Cancel</button></div>`,`document.getElementById('open-alert').onclick=()=>document.getElementById('alert').hidden=false;cancel.onclick=()=>finish({decision:'cancel'},'Project kept');confirm.onclick=()=>finish({decision:'delete'},'Project deleted');`),

  'radio-switch':()=>shell('radio-switch','Billing settings',`<fieldset><legend>Plan</legend><label><input type="radio" name="plan" value="starter" checked>Starter</label><label><input type="radio" name="plan" value="pro">Pro</label><label><input type="radio" name="plan" value="enterprise">Enterprise</label></fieldset><button id="annual" role="switch" aria-checked="false">Annual billing</button><button id="save">Save billing settings</button>`,`annual.onclick=()=>annual.setAttribute('aria-checked',String(annual.getAttribute('aria-checked')!=='true'));save.onclick=()=>finish({plan:document.querySelector('[name=plan]:checked').value,annual:annual.getAttribute('aria-checked')==='true'});`),

  'toggle-group':()=>shell('toggle-group','View settings',`<h2>Alignment</h2><div id="alignment"><button aria-pressed="true" data-value="left">Left</button><button aria-pressed="false" data-value="center">Center</button><button aria-pressed="false" data-value="right">Right</button></div><h2>Density</h2><div id="density"><button aria-pressed="true" data-value="comfortable">Comfortable</button><button aria-pressed="false" data-value="compact">Compact</button></div><button id="apply">Apply view settings</button>`,`for(const group of [alignment,density])group.querySelectorAll('button').forEach(button=>button.onclick=()=>group.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===button))));apply.onclick=()=>finish({alignment:alignment.querySelector('[aria-pressed=true]').dataset.value,density:density.querySelector('[aria-pressed=true]').dataset.value});`),

  'custom-select':()=>shell('custom-select','Warehouse',`<label id="warehouse-label">Warehouse</label><button id="trigger" role="combobox" aria-labelledby="warehouse-label" aria-haspopup="listbox" aria-expanded="false" aria-readonly="true">Choose warehouse</button><div id="list" role="listbox" aria-labelledby="warehouse-label" hidden><button role="option" data-value="east">East warehouse</button><button role="option" data-value="west">West warehouse</button><button role="option" data-value="central">Central warehouse</button></div><button id="save">Save warehouse</button>`,`let selected='';trigger.onclick=()=>{list.hidden=false;trigger.setAttribute('aria-expanded','true')};list.querySelectorAll('[role=option]').forEach(option=>option.onclick=()=>{selected=option.dataset.value;trigger.textContent=option.textContent;list.hidden=true;trigger.setAttribute('aria-expanded','false')});save.onclick=()=>selected&&finish({warehouse:selected});`),

  'multi-select':()=>shell('multi-select','Team access',`<div role="listbox" aria-label="Teams" aria-multiselectable="true"><button role="option" aria-selected="false" data-value="analytics">Analytics</button><button role="option" aria-selected="false" data-value="design">Design</button><button role="option" aria-selected="false" data-value="security">Security</button></div><button id="apply">Apply teams</button>`,`document.querySelectorAll('[role=option]').forEach(option=>option.onclick=()=>option.setAttribute('aria-selected',String(option.getAttribute('aria-selected')!=='true')));apply.onclick=()=>finish({teams:[...document.querySelectorAll('[role=option][aria-selected=true]')].map(x=>x.dataset.value).sort()});`),

  pagination:()=>shell('pagination','Invoices',`<div id="rows"></div><nav aria-label="Invoice pages"><button data-page="1">1</button><button data-page="2">2</button><button data-page="3">3</button><button id="next">Next</button></nav>`,`let page=1;function draw(){rows.innerHTML=page===3?'<article><h2>Invoice 27</h2><button id="open27">Open Invoice 27</button></article><article><h2>Invoice 28</h2></article>':'<p>Invoices '+((page-1)*10+1)+'–'+(page*10)+'</p>';if(page===3)open27.onclick=()=>finish({page,invoice:'27'})}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);draw()});next.onclick=()=>{page=Math.min(3,page+1);draw()};draw();`),

  'sortable-table':()=>shell('sortable-table','Projects',`<table><thead><tr><th><button id="sort">Sort by name</button></th><th>Owner</th><th>Action</th></tr></thead><tbody id="body"></tbody></table>`,`let direction='none';const rows=[['Zephyr','Mina'],['Orion','Kai'],['Atlas','Rae']];function draw(){const ordered=direction==='name-ascending'?[...rows].sort((a,b)=>a[0].localeCompare(b[0])):rows;body.innerHTML=ordered.map(r=>'<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td><button data-project="'+r[0]+'">Open '+r[0]+'</button></td></tr>').join('');body.querySelectorAll('button').forEach(b=>b.onclick=()=>finish({sort:direction,project:b.dataset.project}))}sort.onclick=()=>{direction='name-ascending';sort.textContent='Name sorted ascending';draw()};draw();`),

  'tree-view':()=>shell('tree-view','Reports',`<div role="tree" aria-label="Report folders"><button id="finance" role="treeitem" aria-expanded="false">Finance</button><div id="finance-children" role="group" hidden><button role="treeitem" data-report="Q3 forecast">Q3 forecast</button><button role="treeitem" data-report="Q4 forecast">Q4 forecast</button></div><button role="treeitem">Operations</button></div><button id="open-report" disabled>Open selected report</button>`,`let selected='';finance.onclick=()=>{finance.setAttribute('aria-expanded','true');document.getElementById('finance-children').hidden=false};document.querySelectorAll('[data-report]').forEach(x=>x.onclick=()=>{selected=x.dataset.report;document.getElementById('open-report').disabled=false});document.getElementById('open-report').onclick=()=>finish({branch:'Finance',report:selected});`),

  'command-palette':()=>shell('command-palette','Workspace',`<button id="open-palette">Open command palette</button><dialog id="palette"><h2>Commands</h2><label>Search commands <input id="query" role="combobox" aria-controls="commands" aria-expanded="false" autocomplete="off"></label><div id="commands" role="listbox"></div></dialog>`,`let timer;document.getElementById('open-palette').onclick=()=>document.getElementById('palette').showModal();query.oninput=()=>{clearTimeout(timer);commands.innerHTML='';query.setAttribute('aria-expanded','false');timer=setTimeout(()=>{commands.innerHTML='<button role="option">Create folder</button><button id="create" role="option">Create report</button>';query.setAttribute('aria-expanded','true');document.getElementById('create').onclick=()=>finish({command:'Create report'})},250)};`),

  'popover-filters':()=>shell('popover-filters','Orders',`<button id="trigger" aria-haspopup="dialog" aria-expanded="false">Filters</button><div id="popover" role="dialog" aria-label="Filters" hidden><label><input id="overdue" type="checkbox">Overdue</label><label><input id="unassigned" type="checkbox">Unassigned</label><button id="apply">Apply filters</button></div>`,`trigger.onclick=()=>{popover.hidden=false;trigger.setAttribute('aria-expanded','true')};apply.onclick=()=>finish({overdue:overdue.checked,unassigned:unassigned.checked});`),

  stepper:()=>shell('stepper','Create project',`<p id="step">Step 1 of 3</p><div id="stage"><button id="begin">Begin</button></div>`,`const html=s=>stage.innerHTML=s;begin.onclick=()=>{step.textContent='Step 2 of 3';html('<label>Project name <input id="project"></label><label>Access <select id="access"><option value="public">Public</option><option value="private">Private</option></select></label><button id="review">Review</button>');review.onclick=()=>{const data={name:project.value,access:access.value};step.textContent='Step 3 of 3';html('<h2>Review project</h2><p>'+data.name+' · '+data.access+'</p><button id="create">Create project</button>');create.onclick=()=>finish(data)}};`),

  drawer:()=>shell('drawer','Account home',`<button id="open-drawer">Open account drawer</button><aside id="drawer" role="dialog" aria-modal="true" aria-label="Account" hidden><h2>Account</h2><button data-destination="Profile">Profile</button><button data-destination="API keys">API keys</button><button data-destination="Sessions">Sessions</button></aside>`,`document.getElementById('open-drawer').onclick=()=>document.getElementById('drawer').hidden=false;document.getElementById('drawer').querySelectorAll('[data-destination]').forEach(x=>x.onclick=()=>finish({destination:x.dataset.destination}));`),

  carousel:()=>shell('carousel','Featured stays',`<div class="slides" aria-live="polite"><article><h2 id="stay"></h2><button id="choose">Choose this stay</button></article></div><button id="previous">Previous slide</button><button id="next">Next slide</button>`,`const stays=['City loft','Coastal cottage','Alpine lodge'];let index=0;function draw(){stay.textContent=stays[index]}previous.onclick=()=>{index=(index+stays.length-1)%stays.length;draw()};next.onclick=()=>{index=(index+1)%stays.length;draw()};choose.onclick=()=>finish({stay:stays[index]});draw();`),

  'delayed-toast':()=>shell('delayed-toast','Data sync',`<button id="sync">Run sync</button><p id="sync-status" role="status">Idle</p>`,`sync.onclick=async()=>{const message=document.getElementById('sync-status');sync.disabled=true;message.textContent='Sync running';await emit({type:'started',caseId});setTimeout(async()=>{message.textContent='Sync complete';message.className='toast';await emit({type:'complete',caseId,value:{status:'Sync complete'}})},700)};`),

  spinbutton:()=>shell('spinbutton','Capacity',`<label>Seats <input id="seats" type="number" min="1" max="20" value="4"></label><button id="save">Save capacity</button>`,`save.onclick=()=>finish({seats:Number(seats.value)});`),

  'tri-state-checkbox':()=>shell('tri-state-checkbox','Notification channels',`<label><input id="all" type="checkbox">All channels</label><label><input class="child" id="email" type="checkbox" checked>Email</label><label><input class="child" id="sms" type="checkbox">SMS</label><label><input class="child" id="push" type="checkbox">Push</label><button id="save">Save channels</button>`,`const children=[email,sms,push];function state(){all.checked=children.every(x=>x.checked);all.indeterminate=!all.checked&&children.some(x=>x.checked)}all.onchange=()=>{children.forEach(x=>x.checked=all.checked);state()};children.forEach(x=>x.onchange=state);save.onclick=()=>finish({email:email.checked,sms:sms.checked,push:push.checked});state();`),

  rating:()=>shell('rating','Review',`<div role="radiogroup" aria-label="Rating"><button role="radio" aria-checked="false" data-rating="1">1 star</button><button role="radio" aria-checked="false" data-rating="2">2 stars</button><button role="radio" aria-checked="false" data-rating="3">3 stars</button><button role="radio" aria-checked="false" data-rating="4">4 stars</button><button role="radio" aria-checked="false" data-rating="5">5 stars</button></div><button id="submit">Submit review</button>`,`let rating=0;document.querySelectorAll('[data-rating]').forEach(x=>x.onclick=()=>{rating=Number(x.dataset.rating);document.querySelectorAll('[data-rating]').forEach(y=>y.setAttribute('aria-checked',String(y===x)))});submit.onclick=()=>rating&&finish({rating});`),

  breadcrumb:()=>shell('breadcrumb','Notification rules',`<nav aria-label="Breadcrumb"><ol><li><a href="#home">Home</a></li><li><a id="workspace" href="#workspace">Workspace</a></li><li aria-current="page">Notification rules</li></ol></nav><div id="content"><p>Choose a workspace section.</p></div>`,`workspace.onclick=e=>{e.preventDefault();content.innerHTML='<h2>Workspace</h2><a id="notifications" href="#notifications">Notifications</a><a href="#members">Members</a>';notifications.onclick=e=>{e.preventDefault();finish({destination:'Notifications'})}};`),

  'missing-target':()=>shell('missing-target','Settings',`<p>Profile and security settings are available.</p><button>Open profile settings</button><button>Open security settings</button>`),
  'file-upload':()=>shell('file-upload','Contract submission',`<label>Contract file <input type="file" id="contract" accept="application/pdf"></label><button id="submit">Submit contract</button>`,`submit.onclick=()=>{if(contract.files.length)finish({uploaded:true})};`),
  'hover-card':()=>shell('hover-card','Team',`<button id="account" aria-describedby="hint">Account</button><p id="hint">Hover to reveal account links.</p><div id="card" hidden><a id="shortcuts" href="#shortcuts">Keyboard shortcuts</a></div>`,`account.onmouseenter=()=>card.hidden=false;shortcuts.onclick=e=>{e.preventDefault();finish({destination:'Keyboard shortcuts'})};`),
};

export function componentPage(pathname) {
  const id = decodeURIComponent(pathname.replace(/^\/components\//,'').split('?')[0]);
  const render = pages[id];
  return render ? render() : shell('missing','Component not found','<p>No fixture exists for this path.</p>');
}
